def normalizar(texto):
    texto = unicodedata.normalize('NFKD', str(texto))
    return ''.join(c for c in texto if not unicodedata.combining(c)).strip().casefold()


def base_original():
    return pd.DataFrame([
        dict(zip(COLUNAS, item['values']), Documento=item['source'])
        for item in DADOS_ORIGINAIS
    ])


def ler_arquivo(conteudo, nome):
    """Importa a primeira aba de Excel ou CSV com separador detectado."""
    if nome.lower().endswith('.xlsx'):
        tabela = pd.read_excel(BytesIO(conteudo), dtype=str, engine='openpyxl')
    else:
        try:
            texto = conteudo.decode('utf-8-sig')
        except UnicodeDecodeError:
            texto = conteudo.decode('cp1252')
        tabela = pd.read_csv(StringIO(texto), sep=None, engine='python', dtype=str)
    nomes = {normalizar(c): c for c in COLUNAS}
    tabela = tabela.rename(columns={c: nomes.get(normalizar(c), c) for c in tabela.columns})
    if tabela.columns.duplicated().any():
        raise ValueError('O arquivo possui nomes de colunas duplicados.')
    faltantes = [c for c in COLUNAS if c not in tabela.columns]
    if faltantes:
        raise ValueError('Colunas obrigatórias ausentes: ' + ', '.join(faltantes))
    tabela = tabela[COLUNAS].fillna('').astype(str)
    for coluna in COLUNAS:
        tabela[coluna] = tabela[coluna].str.strip()
    tabela = tabela.loc[tabela.ne('').any(axis=1)].copy()
    if tabela.empty:
        raise ValueError('O arquivo não contém registros.')
    incompletas = tabela.eq('').any(axis=1)
    if incompletas.any():
        raise ValueError(f'{int(incompletas.sum())} linha(s) com produto, ensaio ou frequência em branco. Preencha esses campos antes de importar.')
    tabela['Documento'] = nome
    return tabela.reset_index(drop=True)


def filtrar(tabela, produtos=None, ensaios=None, frequencias=None, busca=''):
    resultado = tabela.copy()
    for coluna, valores in zip(COLUNAS, [produtos, ensaios, frequencias]):
        if valores:
            resultado = resultado.loc[resultado[coluna].isin(valores)]
    if busca.strip():
        termo = normalizar(busca)
        mascara = resultado[COLUNAS].apply(
            lambda col: col.map(normalizar).str.contains(termo, regex=False)
        ).any(axis=1)
        resultado = resultado.loc[mascara]
    return resultado.reset_index(drop=True)


def gerar_excel(tabela):
    """Exporta somente as três colunas e guarda a origem em notas."""
    buffer = BytesIO()
    with pd.ExcelWriter(buffer, engine='openpyxl') as writer:
        tabela[COLUNAS].to_excel(writer, sheet_name='Plano da Qualidade', index=False)
        aba = writer.sheets['Plano da Qualidade']
        aba.freeze_panes = 'A2'
        aba.auto_filter.ref = aba.dimensions
        for celula in aba[1]:
            celula.fill = PatternFill('solid', fgColor='17365D')
            celula.font = Font(color='FFFFFF', bold=True)
        for coluna, largura in [('A', 45), ('B', 62), ('C', 38)]:
            aba.column_dimensions[coluna].width = largura
        for numero, (_, registro) in enumerate(tabela.iterrows(), 2):
            for coluna in range(1, 4):
                celula = aba.cell(numero, coluna)
                # Valores importados são texto, nunca fórmulas executáveis.
                celula.data_type = 's'
                celula.alignment = Alignment(wrap_text=True, vertical='center')
            origem = registro.get('Documento', '')
            if origem:
                aba.cell(numero, 1).comment = Comment(f'Fonte: {origem}', 'Fonte documental')
    return buffer.getvalue()


