def tabela_html(tabela):
    """Escapa todo conteúdo importado antes de apresentá-lo como HTML."""
    cabecalho = ''.join(f'<th scope="col">{escape(c)}</th>' for c in COLUNAS)
    linhas = ''.join('<tr>' + ''.join(f'<td>{escape(str(valor))}</td>' for valor in linha) + '</tr>'
                     for linha in tabela[COLUNAS].itertuples(index=False, name=None))
    if not linhas:
        linhas = '<tr><td colspan="3">Nenhum registro corresponde aos filtros selecionados.</td></tr>'
    return f'<div class="pq-table-wrap" role="region" aria-label="Plano de análises internas" tabindex="0"><table class="pq-table"><thead><tr>{cabecalho}</tr></thead><tbody>{linhas}</tbody></table></div>'



def main():
    st.set_page_config(page_title='Plano da Qualidade', page_icon='📋', layout='wide')
    st.html(ESTILO)
    st.html('<div class="pq-header"><h1>Plano da Qualidade</h1><div class="pq-meta">Análises internas<br>Produtos, ensaios e frequências analíticas</div></div>')

    with st.expander('Importar uma base atualizada'):
        st.write('Envie Excel (.xlsx) ou CSV com as colunas Produto, Ensaio e Frequência. No Excel, será lida a primeira aba.')
        arquivo = st.file_uploader('Selecionar arquivo', type=['xlsx', 'csv'])
        confirmar_internas = st.checkbox('Confirmo que o arquivo contém somente análises internas.', value=False)
        st.caption('As três colunas não identificam o laboratório executor. Importe uma base já restrita às análises internas.')
        st.caption('A importação substitui a base apenas nesta sessão. Remova o arquivo para retornar aos dados dos anexos. Para guardar a atualização, baixe o Excel.')
    tabela = base_original()
    if arquivo is not None:
        if not confirmar_internas:
            st.info('Confirme que a base importada contém somente análises internas para continuar.')
            st.stop()
        try:
            tabela = ler_arquivo(arquivo.getvalue(), arquivo.name)
        except Exception as erro:
            st.error(f'Não foi possível importar o arquivo: {erro}')
            st.stop()

    with st.container(key='filtros'):
        st.html('<h2 class="pq-heading">Filtros das análises</h2><div class="pq-note">Selecione o plano e combine os filtros para atualizar os cartões e a tabela.</div>')
        documento = st.selectbox('Plano da Qualidade', ['Todos'] + sorted(tabela['Documento'].unique().tolist()))
        if documento != 'Todos':
            tabela = tabela.loc[tabela['Documento'].eq(documento)]
        f1, f2, f3 = st.columns(3)
        produtos = f1.multiselect('Produto', sorted(tabela['Produto'].unique()), placeholder='Todos')
        ensaios = f2.multiselect('Ensaio', sorted(tabela['Ensaio'].unique()), placeholder='Todos')
        frequencias = f3.multiselect('Frequência', sorted(tabela['Frequência'].unique()), placeholder='Todas')
        busca = st.text_input('Buscar na tabela', placeholder='Digite um produto ou ensaio')

    resultado = filtrar(tabela, produtos, ensaios, frequencias, busca)
    c1, c2, c3 = st.columns(3)
    c1.metric('Registros exibidos', len(resultado))
    c2.metric('Produtos', resultado['Produto'].nunique())
    c3.metric('Ensaios distintos', resultado['Ensaio'].nunique())
    with st.container(key='tabela'):
        st.html('<h2 class="pq-heading">Plano de análises internas</h2>')
        st.html(f'<div class="pq-note">{len(resultado)} registros exibidos · frequências conforme os planos selecionados</div>')
        st.html(tabela_html(resultado))
        st.download_button('Baixar tabela filtrada em Excel', gerar_excel(resultado),
            file_name='Plano_Qualidade_Filtrado.xlsx',
            mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', disabled=resultado.empty)
    with st.expander('Sobre os dados'):
        st.write('A base inicial contém 728 registros internos dos 12 anexos fornecidos. Foram excluídos 247 registros de análises externas. A classificação considera o campo Laboratório Responsável do plano de levedura seca e a indicação de método interno ME.GSM. ou Lab. externo dos demais anexos. As frequências e repetições foram mantidas conforme os documentos. Os registros não representam uma quantidade de análises previstas por dia.')
        st.write('Há registros de um mesmo ensaio com frequências distintas. Confira o documento de origem antes de utilizar a base no cálculo de aderência. Os campos Volume gasto, Fator e Peso da amostra da soda cáustica são auxiliares do cálculo de pureza.')
        st.write('Esta versão organiza o plano. O cálculo de aderência requer os resultados realizados e as regras de comparação.')


if __name__ == '__main__':
    main()
